pub fn timberframe_audio_init_system<S: Studio + Send + Sync + 'static>(
    core: Res<AudioCore<S>>,
    mut commands: Commands,
) {
    commands.insert_resource(TimberframeAudioState::<S::Event>::new(&core));
}

